package com.huy.enterprise.inventory; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/inventory") @RequiredArgsConstructor public class InventoryController {private final InventoryService service;@GetMapping List<InventoryResponse> all(){return service.all();}@GetMapping("/low-stock") List<InventoryResponse> low(){return service.low();}@GetMapping("/{id}") InventoryResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) InventoryResponse create(@Valid @RequestBody InventoryRequest r){return service.save(null,r);}@PutMapping("/{id}") InventoryResponse update(@PathVariable UUID id,@Valid @RequestBody InventoryRequest r){return service.save(id,r);}}
